		pool = edge
	}
	p := pool[(g.next()>>8)%uint64(len(pool))]
	v := 1
	if (g.next()>>8)%8 == 0 {
		v = Merge
	}
	g.cells[p[0]][p[1]] = v
	return p[0], p[1], v
