func (g *Game) Score() int { return g.score }

// Over reports whether no move is possible.
func (g *Game) Over() bool { return len(g.LegalMoves()) == 0 }

// Render draws the board.
func (g *Game) Render() string {
	maxv := 0
	for r := 0; r < N; r++ {
		for c := 0; c < N; c++ {
			if g.cells[r][c] > maxv {
				maxv = g.cells[r][c]
			}
		}
	}
